48	const PROCESSING_FEE = 5;
49	
50	const BASE_PREMIUMS = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	} as const satisfies Record<string, number>;
58	
59	type InsurableItemType = keyof typeof BASE_PREMIUMS;
60	
61	const basePremiumOf = (item: Item): number =>
62	  BASE_PREMIUMS[item.type as InsurableItemType];
63	
64	/** Premiums are rounded up — in MHPCO's favour. */
65	const roundPremium = (amount: number): number => Math.ceil(amount);
66	
67	const COMPONENT_BLOCK_SIZE = 3;
68	const COMPONENT_BLOCK_PREMIUM = 60;
69	
70	/** Items of a single type, kept together so the block rule can be applied. */
71	type SameTypeGroup = Item[];
72	
73	const groupByType = (items: Item[]): SameTypeGroup[] => {
74	  const groups = new Map<string, SameTypeGroup>();
75	  for (const item of items) {
76	    const group = groups.get(item.type) ?? [];
77	    group.push(item);
78	    groups.set(item.type, group);
79	  }
80	  return [...groups.values()];
81	};
82	
83	const sumBasePremiums = (group: SameTypeGroup): number =>
84	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
85	
86	/**
87	 * Exactly three alike items form a building block priced at a flat premium;
88	 * any other count is priced per item.
89	 */
90	const blockAwareBasePremium = (group: SameTypeGroup): number =>
91	  group.length === COMPONENT_BLOCK_SIZE
92	    ? COMPONENT_BLOCK_PREMIUM
93	    : sumBasePremiums(group);
94	
95	const policyBasePremiumFor = (items: Item[]): number =>
96	  groupByType(items).reduce(
97	    (sum, group) => sum + blockAwareBasePremium(group),
98	    0,
99	  );
100	
101	const HIGH_ENCHANTMENT_LEVEL = 5;
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
106	
107	/**
108	 * An item-specific surcharge: when the item triggers the clause, it is charged
109	 * a rate of that item's own base premium — never of the whole policy's.
110	 */
111	interface ItemSurcharge {
112	  appliesTo: (item: Item) => boolean;
113	  rate: number;
114	}
115	
116	const ITEM_SURCHARGES: ItemSurcharge[] = [
117	  { appliesTo: isCursed, rate: 0.5 },
118	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
119	];
120	
121	/** Every clause the item triggers stacks, each on that item's base premium. */
122	const surchargeRateFor = (item: Item): number =>
123	  ITEM_SURCHARGES.reduce(
124	    (rate, surcharge) =>
125	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
126	    0,
127	  );
128	
129	const itemSurchargesFor = (items: Item[]): number =>
130	  items.reduce(
131	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
132	    0,
133	  );
134	
135	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
136	const LOYALTY_DISCOUNT_RATE = -0.2;
137	const LOYALTY_YEARS = 2;
138	
139	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
140	
141	/** What the MHPCO knows about the customer when pricing a particular quote. */
142	interface QuoteContext {
143	  customer: Customer;
144	  previousContracts: number;
145	}
146	
147	/** Every item in a quote is treated as a first insurance, whatever the history. */
148	const isFirstInsurance = (_context: QuoteContext): boolean => true;
149	const isLoyal = ({ customer }: QuoteContext): boolean =>
150	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
151	const isFollowUpContract = ({ previousContracts }: QuoteContext): boolean =>
152	  previousContracts > 0;
153	
154	/**
155	 * A policy-wide modifier: when the customer triggers the clause, the whole
156	 * policy's base premium is adjusted by that rate — never a single item's.
157	 * A negative rate is a discount.
158	 */
159	interface PolicyModifier {
160	  appliesTo: (context: QuoteContext) => boolean;
161	  rate: number;
162	}
163	
164	const POLICY_MODIFIERS: PolicyModifier[] = [
165	  { appliesTo: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
166	  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
167	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_DISCOUNT_RATE },
168	];
169	
170	/** Every clause the customer triggers stacks on the policy base premium. */
171	const policyModifierRateFor = (context: QuoteContext): number =>
172	  POLICY_MODIFIERS.reduce(
173	    (rate, modifier) =>
174	      modifier.appliesTo(context) ? rate + modifier.rate : rate,
175	    0,
176	  );
177	
178	const quotePremium = (items: Item[], context: QuoteContext): number => {
179	  const policyBasePremium = policyBasePremiumFor(items);
180	  return roundPremium(
181	    policyBasePremium +
182	      policyBasePremium * policyModifierRateFor(context) +
183	      itemSurchargesFor(items) +
184	      PROCESSING_FEE,
185	  );
186	};
187	
188	export const runScenario = (scenario: Scenario): ScenarioResult => {
189	  let previousContracts = 0;
190	  const results = scenario.steps.map((step) => {
191	    if (step.op === "quote") {
192	      const context = { customer: scenario.customer, previousContracts };
193	      previousContracts += 1;
194	      return { premium: quotePremium(step.items, context) };
195	    }
196	    throw new Error(`Unsupported step: ${step.op}`);
197	  });
198	  return { results };
199	};
